import{_ as s,a0 as i,w as l,s as u,ao as r,I as n,x as p,a1 as t,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"在Linux上如何清除内存的 Cache、Buffer 和交换空间 | LCTT x X-CMD","titleTemplate":false,"description":"在Linux上如何清除内存的 Cache、Buffer 和交换空间 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Linux上如何清除内存的 Cache、Buffer 和交换空间 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Linux上如何清除内存的 Cache、Buffer 和交换空间 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150610 How to Clear RAM Memory Cache Buffer and Swap Space on Linux","title":"在Linux上如何清除内存的 Cache、Buffer 和交换空间","tag":"201506","desc":""},"relativePath":"201506/20150610 How to Clear RAM Memory Cache Buffer and Swap Space on Linux.md","filePath":"[post].md"}'),c={name:"201506/20150610 How to Clear RAM Memory Cache Buffer and Swap Space on Linux.md"};function d(f,e,m,h,C,x){const a=i("Link");return l(),u("div",null,[e[19]||(e[19]=r(`<h1 id="在linux上如何清除内存的-cache、buffer-和交换空间" tabindex="-1">在Linux上如何清除内存的 Cache、Buffer 和交换空间 <a class="header-anchor" href="#在linux上如何清除内存的-cache、buffer-和交换空间" aria-label="Permalink to “在Linux上如何清除内存的 Cache、Buffer 和交换空间”">​</a></h1><p>像任何其他的操作系统一样，GNU/Linux 已经实现的内存管理不仅有效，而且更好。但是，如果有任何进程正在蚕食你的内存，而你想要清除它的话，Linux 提供了一个刷新或清除RAM缓存方法。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Clear-RAM-Cache-in-Linux.jpg" alt="Clear RAM Cache and Swap in Linux"></p><h3 id="如何在-linux-中清除缓存-cache" tabindex="-1">如何在 Linux 中清除缓存（Cache）？### <a class="header-anchor" href="#如何在-linux-中清除缓存-cache" aria-label="Permalink to “如何在 Linux 中清除缓存（Cache）？###”">​</a></h3><p>每个 Linux 系统有三种选项来清除缓存而不需要中断任何进程或服务。</p><p>（LCTT 译注：Cache，译作“缓存”，指 CPU 和内存之间高速缓存。Buffer，译作“缓冲区”，指在写入磁盘前的存储再内存中的内容。在本文中，Buffer 和 Cache 有时候会通指。）</p><ol><li><p>仅清除页面缓存（PageCache）</p><pre><code> # sync; echo 1 &gt; /proc/sys/vm/drop_caches		
</code></pre></li><li><p>清除目录项和inode</p><pre><code> # sync; echo 2 &gt; /proc/sys/vm/drop_caches		
</code></pre></li><li><p>清除页面缓存，目录项和inode</p><pre><code> # sync; echo 3 &gt; /proc/sys/vm/drop_caches 
</code></pre></li></ol><p>上述命令的说明：</p>`,8)),n("p",null,[e[1]||(e[1]=p("sync 将刷新文件系统缓冲区（buffer），命令通过“;”分隔，顺序执行，shell在执行序列中的下一个命令之前会等待命令的终止。正如内核文档中提到的，写入到drop_cache将清空缓存而不会杀死任何应用程序/服务，",-1)),t(a,{href:"https://linux.cn/article-3592-1.html"},{default:o(()=>[...e[0]||(e[0]=[p("echo命令",-1)])]),_:1}),e[2]||(e[2]=p("做写入文件的工作。",-1))]),e[20]||(e[20]=r(`<p>如果你必须清除磁盘高速缓存，第一个命令在企业和生产环境中是最安全，<code>&quot;...echo 1&gt; ...&quot;</code>只会清除页面缓存。 在生产环境中不建议使用上面的第三个选项<code>&quot;...echo 3 &gt; ...&quot;</code> ，除非你明确自己在做什么，因为它会清除缓存页，目录项和inodes。</p><p><strong>在Linux上释放也许被内核所使用的缓冲区（Buffer）和缓存（Cache）是否是个好主意？</strong></p><p>当你设置许多设定想要检查效果时，如果它实际上是专门针对 I/O 范围的基准测试，那么你可能需要清除缓冲区和缓存。你可以如上所示删除缓存，无需重新启动系统（即无需停机）。</p><p>Linux被设计成它在寻找磁盘之前到磁盘缓存寻找的方式。如果它发现该资源在缓存中，则该请求不会发送到磁盘。如果我们清理缓存，磁盘缓存就起不到作用了，系统会到磁盘上寻找资源。</p><p>此外，当清除缓存后它也将减慢系统运行速度，系统会将每一个被请求的资源再次加载到磁盘缓存中。</p><p>现在，我们将创建一个 shell 脚本，通过一个 cron 调度任务在每天下午2点自动清除RAM缓存。如下创建一个 shell 脚本 clearcache.sh 并在其中添加以下行：</p><pre><code>#!/bin/bash
# 注意，我们这里使用了 &quot;echo 3&quot;，但是不推荐使用在产品环境中，应该使用 &quot;echo 1&quot;
echo &quot;echo 3 &amp;gt; /proc/sys/vm/drop_caches&quot;
</code></pre><p>给clearcache.sh文件设置执行权限</p><pre><code># chmod 755 clearcache.sh
</code></pre><p>现在，当你需要清除内存缓存时只需要调用脚本。</p><p>现在设置一个每天下午2点的定时任务来清除RAM缓存，打开crontab进行编辑。</p><pre><code># crontab -e
</code></pre><p>添加以下行，保存并退出。</p><pre><code>0 3 * * * /path/to/clearcache.sh
</code></pre>`,14)),n("p",null,[e[4]||(e[4]=p("有关如何创建一个定时任务，更多细节你可以查看我们的文章 ",-1)),t(a,{href:"http://www.tecmint.com/11-cron-scheduling-task-examples-in-linux/"},{default:o(()=>[...e[3]||(e[3]=[p("11 个定时调度任务的例子",-1)])]),_:1}),e[5]||(e[5]=p("。",-1))]),e[21]||(e[21]=r(`<p><strong>在生产环境的服务器上自动清除RAM是否是一个好主意？</strong></p><p>不！它不是。想想一个情况，当你已经预定脚本在每天下午2点来清除内存缓存。那么其时该脚本会执行并刷新你的内存缓存。在某一天由于某些原因，可能您的网站的在线用户会超过预期地从你的服务器请求资源。</p><p>而在这时，按计划调度的脚本运行了，并清除了缓存中的一切。当所有的用户都从磁盘读取数据时，这将导致服务器崩溃并损坏数据库。因此，清除缓存仅在必要时并且在你的预料之中，否则你就是个呆瓜系统管理员。</p><p>###如何清除Linux的交换空间？###</p><p>如果你想清除掉的空间，你可以运行下面的命令：</p><pre><code># swapoff -a &amp;&amp; swapon -a
</code></pre><p>此外，了解有关风险后，您可以将上面的命令添加到cron中。</p><p>现在，我们将上面两种命令结合成一个命令，写成正确的脚本来同时清除RAM缓存和交换空间。</p><pre><code># echo 3 &gt; /proc/sys/vm/drop_caches &amp;&amp; swapoff -a &amp;&amp; swapon -a &amp;&amp; printf &#39;\\n%s\\n&#39; &#39;Ram-cache and Swap Cleared&#39;
</code></pre><p>或</p><pre><code>su -c &#39;echo 3 &gt; /proc/sys/vm/drop_caches&#39; &amp;&amp; swapoff -a &amp;&amp; swapon -a &amp;&amp; printf &#39;\\n%s\\n&#39; &#39;Ram-cache and Swap Cleared&#39;
</code></pre><p>在测试上面的命令之前，我们在执行脚本前后运行“free -m” 来检查缓存。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Clear-RAM-Cache.gif" alt="Clear RAM Cache and Swap Space"></p><p>就是这样，如果你喜欢这篇文章，不要忘记向我们提供您宝贵的意见，让我们知道，您认为在企业和生产环境中清除内存缓存和缓冲区是否是一个好主意？</p><hr>`,15)),n("p",null,[e[7]||(e[7]=p("via: ",-1)),t(a,{href:"http://www.tecmint.com/clear-ram-memory-cache-buffer-and-swap-space-on-linux/"},{default:o(()=>[...e[6]||(e[6]=[p("http://www.tecmint.com/clear-ram-memory-cache-buffer-and-swap-space-on-linux/",-1)])]),_:1})]),n("p",null,[e[11]||(e[11]=p("作者：",-1)),t(a,{href:"http://www.tecmint.com/author/avishek/"},{default:o(()=>[...e[8]||(e[8]=[p("Avishek Kumar",-1)])]),_:1}),e[12]||(e[12]=p(" 译者：",-1)),t(a,{href:"https://github.com/strugglingyouth"},{default:o(()=>[...e[9]||(e[9]=[p("strugglingyouth",-1)])]),_:1}),e[13]||(e[13]=p(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:o(()=>[...e[10]||(e[10]=[p("wxy",-1)])]),_:1})]),n("p",null,[e[16]||(e[16]=p("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[14]||(e[14]=[p("LCTT",-1)])]),_:1}),e[17]||(e[17]=p(" 原创翻译，",-1)),t(a,{href:"https://linux.cn/"},{default:o(()=>[...e[15]||(e[15]=[p("Linux中国",-1)])]),_:1}),e[18]||(e[18]=p(" 荣誉推出",-1))])])}const g=s(c,[["render",d]]);export{_ as __pageData,g as default};
